import clsx from 'clsx';
import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { VscLibrary } from 'react-icons/vsc';
import { RiBookmarkFill, RiBookmarkLine, RiQuillPenLine, RiTranslate } from 'react-icons/ri';
import { MdOutlineMenu } from 'react-icons/md';
import { FaHeadphones } from 'react-icons/fa6';

import { useEnv } from '@/context/EnvContext';
import { useTranslation } from '@/hooks/useTranslation';
import { useThemeStore } from '@/store/themeStore';
import { useReaderStore } from '@/store/readerStore';
import { useBookDataStore } from '@/store/bookDataStore';
import { useSidebarStore } from '@/store/sidebarStore';
import { useNotebookStore } from '@/store/notebookStore';
import { useSettingsStore } from '@/store/settingsStore';
import { eventDispatcher } from '@/utils/event';
import { saveViewSettings } from '@/helpers/settings';
import { isTranslationAvailable } from '@/services/translators/utils';
import { isCfiInLocation } from '@/utils/cfi';
import { isHiddenAnnotationToolType } from '@/utils/annotationToolbar';
import { getCurrentPage } from '@/utils/book';
import { uniqueId } from '@/utils/misc';
import { nextBooknoteStamp } from '@/utils/booknoteStamp';
import { BookNote } from '@/types/book';
import { HighlighterIcon } from '@/components/HighlighterIcon';
import ModalPortal from '@/components/ModalPortal';
import ViewMenu from './ViewMenu';
import SyncInfoDialog from './SyncInfoDialog';
import { getHighlightColorHex } from '../utils/annotatorUtil';

/**
 * Floating radial dial that replaces the reader header tools on desktop.
 *
 * Behaviour (per design):
 *   - collapsed by default, parked in the top-left corner
 *   - short tap  -> back to the bookshelf
 *   - long press -> expand the tool ring
 *   - drag       -> move anywhere; the position is persisted
 *
 * Visual: Uiverse "pretty-dolphin-68" by dexter-st (morphing hamburger +
 * option ring + conic selector arc), prefixed `rd-` in globals.css.
 */

const LONG_PRESS_MS = 500;
const DRAG_THRESHOLD = 10;
const EDGE = 12;
const DIAL_SIZE = 44;
const RING_RADIUS = 56; // button/2 + ring-dist + ring-thickness
const SHIFT_MARGIN = 8;
const POS_KEY = 'readest.readerDial.position';

interface DialPosition {
  x: number;
  y: number;
}

const clampPosition = (x: number, y: number): DialPosition => ({
  x: Math.min(Math.max(EDGE, x), Math.max(EDGE, window.innerWidth - DIAL_SIZE - EDGE)),
  y: Math.min(Math.max(EDGE, y), Math.max(EDGE, window.innerHeight - DIAL_SIZE - EDGE)),
});

const loadPosition = (): DialPosition => {
  try {
    const raw = localStorage.getItem(POS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<DialPosition>;
      if (typeof parsed.x === 'number' && typeof parsed.y === 'number') {
        return clampPosition(parsed.x, parsed.y);
      }
    }
  } catch {
    // ignore corrupted storage
  }
  return { x: EDGE + 4, y: EDGE + 4 };
};

interface ReaderDialProps {
  bookKey: string;
  onGoToLibrary: () => void;
}

interface DialTool {
  key: string;
  label: string;
  icon: React.ReactNode;
  onSelect: () => void;
  /** highlighted in the ring (e.g. bookmark present, TTS playing) */
  active?: boolean;
  disabled?: boolean;
}

const ReaderDial: React.FC<ReaderDialProps> = ({ bookKey, onGoToLibrary }) => {
  const _ = useTranslation();
  const { envConfig, appService } = useEnv();
  const { settings } = useSettingsStore();
  const { isDarkMode } = useThemeStore();
  const { getConfig, saveConfig, getBookData, updateBooknotes } = useBookDataStore();
  const {
    getProgress,
    getViewState,
    getViewSettings,
    setViewSettings,
    setBookmarkRibbonVisibility,
    setHoveredBookKey,
  } = useReaderStore();
  const { sideBarBookKey, setSideBarBookKey } = useSidebarStore();
  const { isNotebookVisible, toggleNotebook } = useNotebookStore();

  const [position, setPosition] = useState<DialPosition>(loadPosition);
  const [expanded, setExpanded] = useState(false);
  const [selected, setSelected] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [shift, setShift] = useState<DialPosition>({ x: 0, y: 0 });
  const [viewMenuOpen, setViewMenuOpen] = useState(false);
  const [isMetaHashDialogOpen, setIsMetaHashDialogOpen] = useState(false);
  const [isBookmarked, setIsBookmarked] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const dragState = useRef<{
    x0: number;
    y0: number;
    originX: number;
    originY: number;
    dragged: boolean;
    longPressFired: boolean;
  } | null>(null);

  useEffect(
    () => () => {
      if (longPressTimer.current) clearTimeout(longPressTimer.current);
    },
    [],
  );

  // Keep the dial inside the viewport when the window shrinks.
  useEffect(() => {
    const handleResize = () => setPosition((prev) => clampPosition(prev.x, prev.y));
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Parked in a corner the expanded ring would be clipped by the viewport, so
  // while open the dial slides just enough inward for the whole ring to show.
  // Dragging cancels the slide transition (rd-dragging) to stay 1:1 with the
  // pointer.
  useLayoutEffect(() => {
    if (!expanded) {
      setShift({ x: 0, y: 0 });
      return;
    }
    const cx = position.x + DIAL_SIZE / 2;
    const cy = position.y + DIAL_SIZE / 2;
    const r = RING_RADIUS + SHIFT_MARGIN;
    let dx = 0;
    if (cx - r < 0) dx = r - cx;
    else if (cx + r > window.innerWidth) dx = window.innerWidth - r - cx;
    let dy = 0;
    if (cy - r < 0) dy = r - cy;
    else if (cy + r > window.innerHeight) dy = window.innerHeight - r - cy;
    setShift({ x: dx, y: dy });
  }, [expanded, position]);

  // ----- per-book state -------------------------------------------------
  const config = getConfig(bookKey);
  const progress = getProgress(bookKey);
  const viewSettings = getViewSettings(bookKey);
  const viewState = getViewState(bookKey);
  const bookData = getBookData(bookKey);

  // Mirrors BookmarkToggler: the header copy is hidden while the dial owns
  // these tools, so the dial also keeps the pull-down ribbon in sync.
  useEffect(() => {
    const { booknotes = [] } = config || {};
    const { location: cfi } = progress || {};
    if (!cfi) return;
    const locationBookmarked = booknotes
      .filter((booknote) => booknote.type === 'bookmark' && !booknote.deletedAt)
      .some((item) => isCfiInLocation(item.cfi, cfi));
    setIsBookmarked(locationBookmarked);
    setBookmarkRibbonVisibility(bookKey, locationBookmarked);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config, progress, bookKey]);

  const translationEnabled = !!viewSettings?.translationEnabled;
  const translationAvailable = isTranslationAvailable(
    bookData?.book,
    viewSettings?.translateTargetLang,
  );
  const storedQuickAction = viewSettings?.annotationQuickAction;
  const quickAction =
    storedQuickAction && !isHiddenAnnotationToolType(storedQuickAction) ? storedQuickAction : null;
  const highlightActive = quickAction === 'highlight';
  const ttsEnabled = !!viewState?.ttsEnabled;

  const highlightStyle = settings.globalReadSettings.highlightStyle;
  const highlightColor = settings.globalReadSettings.highlightStyles[highlightStyle];
  const highlightHexColor = getHighlightColorHex(settings, highlightColor);

  // ----- tool actions ---------------------------------------------------
  const toggleBookmark = useCallback(() => {
    const data = getBookData(bookKey);
    const bookConfig = getConfig(bookKey);
    const bookProgress = getProgress(bookKey);
    if (!data || !bookConfig || !bookProgress) return;

    const { booknotes: bookmarks = [] } = bookConfig;
    const { location: cfi, range } = bookProgress;
    if (!cfi) return;
    const currentlyBookmarked = getViewState(bookKey)?.ribbonVisible;
    if (!currentlyBookmarked) {
      setIsBookmarked(true);
      const text = range?.startContainer.textContent?.slice(0, 128) || '';
      const truncatedText = text.length === 128 ? text + '...' : text;
      const bookmark: BookNote = {
        id: uniqueId(),
        type: 'bookmark',
        cfi,
        text: truncatedText ? truncatedText : `${getCurrentPage(data.book!, bookProgress)}`,
        note: '',
        page: bookProgress.page,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      const existingBookmark = bookmarks.find(
        (item) => item.type === 'bookmark' && item.cfi === cfi,
      );
      if (existingBookmark) {
        existingBookmark.updatedAt = nextBooknoteStamp(existingBookmark);
        existingBookmark.deletedAt = null;
        existingBookmark.text = bookmark.text;
        existingBookmark.page = bookmark.page;
      } else {
        bookmarks.push(bookmark);
      }
      const updatedConfig = updateBooknotes(bookKey, bookmarks);
      if (updatedConfig) {
        saveConfig(envConfig, bookKey, updatedConfig, settings);
      }
    } else {
      setIsBookmarked(false);
      bookmarks.forEach((item) => {
        if (item.type === 'bookmark' && isCfiInLocation(item.cfi, cfi)) {
          item.deletedAt = nextBooknoteStamp(item);
        }
      });
      const updatedConfig = updateBooknotes(bookKey, bookmarks);
      if (updatedConfig) {
        saveConfig(envConfig, bookKey, updatedConfig, settings);
      }
    }
  }, [bookKey, envConfig, getBookData, getConfig, getProgress, getViewState, saveConfig, settings, updateBooknotes]);

  const toggleTranslation = useCallback(() => {
    const current = getViewSettings(bookKey);
    if (!current) return;
    const next = !current.translationEnabled;
    if (appService?.isMobile) setHoveredBookKey('');
    saveViewSettings(envConfig, bookKey, 'translationEnabled', next, true, false);
    current.translationEnabled = next;
    setViewSettings(bookKey, { ...current });
  }, [appService, bookKey, envConfig, getViewSettings, setHoveredBookKey, setViewSettings]);

  const toggleQuickAction = useCallback(() => {
    const next = highlightActive ? null : 'highlight';
    saveViewSettings(envConfig, bookKey, 'annotationQuickAction', next, false, true);
  }, [bookKey, envConfig, highlightActive]);

  const toggleNotebookView = useCallback(() => {
    if (appService?.isMobile) setHoveredBookKey('');
    if (sideBarBookKey === bookKey) {
      toggleNotebook();
    } else {
      setSideBarBookKey(bookKey);
      if (!isNotebookVisible) toggleNotebook();
    }
  }, [appService, bookKey, isNotebookVisible, setHoveredBookKey, setSideBarBookKey, sideBarBookKey, toggleNotebook]);

  const toggleSpeak = useCallback(() => {
    const state = getViewState(bookKey);
    if (!state) return;
    const eventType = state.ttsEnabled ? 'tts-stop' : 'tts-speak';
    eventDispatcher.dispatch(eventType, { bookKey });
  }, [bookKey, getViewState]);

  // ----- ring options ---------------------------------------------------
  // 注意：书架(library)工具不再放进工具环——收起态的中心按钮本身就是
  // 书架图标，轻点即返回书架；展开态中心变 X 用于收起。环上只放 6 个
  // 真正的阅读工具，避免与中心按钮语义重复。
  const tools: DialTool[] = [
    {
      key: 'bookmark',
      label: isBookmarked ? _('Remove Bookmark') : _('Add Bookmark'),
      icon: isBookmarked ? <RiBookmarkFill size={18} /> : <RiBookmarkLine size={18} />,
      onSelect: toggleBookmark,
      active: isBookmarked,
    },
    {
      key: 'translate',
      label: translationAvailable
        ? translationEnabled
          ? _('Disable Translation')
          : _('Enable Translation')
        : _('Translation Disabled'),
      icon: <RiTranslate size={18} />,
      onSelect: toggleTranslation,
      active: translationEnabled,
      disabled: !translationAvailable && !translationEnabled,
    },
    {
      key: 'highlight',
      label: highlightActive ? _('Disable Highlighter') : _('Enable Highlighter'),
      icon: (
        <HighlighterIcon
          size={18}
          tipColor={highlightHexColor}
          tipStyle={{ opacity: 0.85, mixBlendMode: isDarkMode ? 'screen' : 'multiply' }}
        />
      ),
      onSelect: toggleQuickAction,
      active: highlightActive,
    },
    {
      key: 'notebook',
      label: _('Notebook'),
      icon: <RiQuillPenLine size={18} />,
      onSelect: toggleNotebookView,
    },
    {
      key: 'view',
      label: _('View Options'),
      icon: <MdOutlineMenu size={18} />,
      onSelect: () => setViewMenuOpen(true),
    },
    {
      key: 'speak',
      label: _('Speak'),
      icon: <FaHeadphones size={18} />,
      onSelect: toggleSpeak,
      active: ttsEnabled,
    },
  ];

  const handleOptionSelect = (index: number) => {
    const tool = tools[index]!;
    if (tool.disabled) return;
    setSelected(index);
    tool.onSelect();
    // 点工具后保持展开（用户要求），由中心 X 按钮或点空白处收起。
  };

  // ----- drag / tap / long press ---------------------------------------
  const cancelLongPress = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  };

  const handlePointerDown = (event: React.PointerEvent<HTMLButtonElement>) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    try {
      event.currentTarget.setPointerCapture(event.pointerId);
    } catch {
      // capture is best-effort
    }
    setDragging(true);
    dragState.current = {
      x0: event.clientX,
      y0: event.clientY,
      originX: position.x,
      originY: position.y,
      dragged: false,
      longPressFired: false,
    };
    cancelLongPress();
    longPressTimer.current = setTimeout(() => {
      const state = dragState.current;
      if (state && !state.dragged) {
        state.longPressFired = true;
        setExpanded((prev) => !prev);
      }
    }, LONG_PRESS_MS);
  };

  const handlePointerMove = (event: React.PointerEvent<HTMLButtonElement>) => {
    const state = dragState.current;
    if (!state) return;
    const dx = event.clientX - state.x0;
    const dy = event.clientY - state.y0;
    if (!state.dragged) {
      if (Math.abs(dx) < DRAG_THRESHOLD && Math.abs(dy) < DRAG_THRESHOLD) return;
      state.dragged = true;
      cancelLongPress();
    }
    setPosition(clampPosition(state.originX + dx, state.originY + dy));
  };

  const handlePointerUp = () => {
    cancelLongPress();
    setDragging(false);
    const state = dragState.current;
    dragState.current = null;
    if (!state) return;
    if (state.dragged) {
      try {
        localStorage.setItem(POS_KEY, JSON.stringify(position));
      } catch {
        // storage may be unavailable
      }
      return;
    }
    if (state.longPressFired) return;
    // Short tap: collapse when open, otherwise return to the bookshelf.
    if (expanded) {
      setExpanded(false);
    } else {
      onGoToLibrary();
    }
  };

  // ----- view menu panel ------------------------------------------------
  // 固定定位：贴近右上角，与原版 HeaderBar 的 View 按钮同侧；不随圆盘
  // 拖动而漂移（用户要求"是固定的，不是现在这样"）。
  useLayoutEffect(() => {
    if (!viewMenuOpen || !menuRef.current) return;
    const menu = menuRef.current;
    const rect = menu.getBoundingClientRect();
    const pad = 12;
    let left = window.innerWidth - pad - rect.width;
    if (left < pad) left = pad;
    let top = pad;
    if (top + rect.height > window.innerHeight - pad) {
      top = window.innerHeight - pad - rect.height;
    }
    if (top < pad) top = pad;
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
  }, [viewMenuOpen]);

  const nativeLastSyncedAt =
    Math.max(
      config?.lastSyncedAtConfig || 0,
      config?.lastSyncedAtNotes || 0,
      config?.lastPushedAtConfig || 0,
      config?.lastPushedAtNotes || 0,
    ) || undefined;

  return (
    <>
      <div
        className={clsx('rd-dial', expanded && 'rd-open', dragging && 'rd-dragging')}
        style={
          {
            left: position.x,
            top: position.y,
            transform: `translate(${shift.x}px, ${shift.y}px)`,
            '--selected': selected,
          } as React.CSSProperties
        }
      >
        <div className='rd-options'>
          {tools.map((tool, index) => (
            <div
              key={tool.key}
              className={clsx('rd-option', tool.active && 'rd-active', tool.disabled && 'rd-disabled')}
              style={{ '--i': index } as React.CSSProperties}
              role='button'
              tabIndex={expanded ? 0 : -1}
              aria-label={tool.label}
              aria-disabled={tool.disabled ? true : undefined}
              title={tool.label}
              onClick={() => handleOptionSelect(index)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  handleOptionSelect(index);
                }
              }}
            >
              <span className='rd-option-inner'>{tool.icon}</span>
            </div>
          ))}
        </div>
        <div className='rd-ring' />
        <div className='rd-selector' />
        <button
          type='button'
          className='rd-btn'
          aria-label={expanded ? _('Collapse Menu') : _('Go to Library')}
          aria-expanded={expanded}
          title={expanded ? _('Collapse Menu') : _('Go to Library')}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          onContextMenu={(event) => event.preventDefault()}
        >
          {/* 收起态：中心显示书架图标（轻点=返回书架）；展开态：换回
              汉堡，借 .rd-open 的 CSS 变形成 X（轻点=收起）。 */}
          {expanded ? (
            <svg
              xmlns='http://www.w3.org/2000/svg'
              viewBox='0 0 24 24'
              className='rd-btn-svg'
              fill='none'
              stroke='currentColor'
              strokeWidth='1.5'
              strokeLinecap='round'
              aria-hidden='true'
            >
              <path className='rd-line rd-line-top' d='M4 7 L20 7' />
              <path className='rd-line rd-line-middle' d='M4 12 L20 12' />
              <path className='rd-line rd-line-bottom' d='M4 17 L20 17' />
            </svg>
          ) : (
            <VscLibrary className='rd-btn-lib' aria-hidden='true' />
          )}
        </button>
      </div>

      {expanded && (
        <div
          className='rd-backdrop'
          role='none'
          onPointerDown={() => setExpanded(false)}
        />
      )}

      {viewMenuOpen && (
        <>
          <div
            className='rd-backdrop'
            role='none'
            onPointerDown={() => setViewMenuOpen(false)}
          />
          <div ref={menuRef} className='rd-menu' role='menu'>
            <ViewMenu
              bookKey={bookKey}
              setIsDropdownOpen={() => setViewMenuOpen(false)}
              onShowMetaHashDialog={() => {
                setViewMenuOpen(false);
                setIsMetaHashDialogOpen(true);
              }}
            />
          </div>
        </>
      )}

      {isMetaHashDialogOpen && (
        <ModalPortal showOverlay={false}>
          <SyncInfoDialog
            isOpen={isMetaHashDialogOpen}
            bookKey={bookKey}
            metadata={bookData?.bookDoc?.metadata ?? bookData?.book?.metadata}
            storedMetaHash={bookData?.book?.metaHash}
            nativeLastSyncedAt={nativeLastSyncedAt}
            onClose={() => setIsMetaHashDialogOpen(false)}
          />
        </ModalPortal>
      )}
    </>
  );
};

export default ReaderDial;
